<script setup>
import {computed,ref} from 'vue';import {foodChallenges,simulateStephan} from '../engines/stephanDemineralizationEngine.js';
const emit=defineEmits(['save']);const challenge=ref(foodChallenges[2]);const saliva=ref(1);const fluoride=ref(1450);const xylitol=ref(0);const result=computed(()=>simulateStephan({acid:challenge.value.acidity,saliva:saliva.value,fluoride:fluoride.value,xylitol:xylitol.value}));const points=computed(()=>result.value.rows.map((p,i)=>`${i/(result.value.rows.length-1)*100},${85-(p.ph-3.5)*20}`).join(' '));
</script>
<template><section class="module-card glass"><div class="module-head"><div><div class="eyebrow">03 / Meal-linked pH learning model</div><h2>Stephan curve simulator</h2><p>Explore a simplified plaque-pH recovery curve after common food challenges. Actual oral pH varies and cannot be measured by this model.</p></div><span class="badge">LOCAL MODEL · OFFLINE</span></div><div class="two-col"><div><div class="inner"><h3>Choose a challenge</h3><div class="preset-list"><button v-for="x in foodChallenges" :key="x.name" class="preset" :class="{active:challenge.name===x.name}" @click="challenge=x">{{x.name}}</button></div><div class="control-row"><span class="small">Salivary buffering (model)</span><b>{{saliva.toFixed(1)}}</b></div><input class="range" type="range" min="0.2" max="2" step="0.1" v-model.number="saliva"><div class="control-row"><span class="small">Fluoride scenario (ppm)</span><b>{{fluoride}}</b></div><input class="range" type="range" min="0" max="5000" step="100" v-model.number="fluoride"><div class="control-row"><span class="small">Xylitol scenario</span><b>{{xylitol?'On':'Off'}}</b></div><input class="range" type="range" min="0" max="1" step="1" v-model.number="xylitol"></div><div class="metric-grid"><div class="metric"><span>Model minimum pH</span><b>{{result.minimumPh}}</b></div><div class="metric"><span>Below 5.5</span><b>{{result.dissolutionMinutes}} min</b></div><div class="metric"><span>Model recovery</span><b>{{result.recovery??'—'}} min</b></div></div><button class="action" @click="emit('save',{module:'stephan_ph_logs',challenge:challenge.name,minPh:result.minimumPh,riskMinutes:result.dissolutionMinutes})">Save model run</button></div><div><div class="inner"><h3>Modeled pH over 60 minutes</h3><div class="chart-wrap"><svg class="chart" viewBox="0 0 100 100" preserveAspectRatio="none"><rect x="0" y="0" width="100" height="45" fill="#1f9d7620"/><rect x="0" y="45" width="100" height="20" fill="#e0ad3c1a"/><rect x="0" y="65" width="100" height="35" fill="#e9596120"/><path d="M0 45H100M0 65H100" stroke="#ffffff2a" stroke-dasharray="2 2"/><polyline :points="points" fill="none" stroke="#74ead2" stroke-width="1.4" vector-effect="non-scaling-stroke"/><text x="3" y="12" class="chart-label">pH 7</text><text x="3" y="43" class="chart-label">5.5</text><text x="3" y="63" class="chart-label">4.5</text><text x="87" y="95" class="chart-label">60 min</text></svg></div><div class="legend"><span><i style="background:#36bc83"></i>Recovery zone</span><span><i style="background:#e2b64d"></i>Transition</span><span><i style="background:#e9656c"></i>Model below 5.5</span></div></div><div class="notice" style="margin-top:12px">Brush normally with fluoride toothpaste; do not use this estimate to replace dental advice. Wait before brushing after acidic foods if enamel sensitivity is a concern; ask a dental professional.</div></div></div></section></template>
